OmniUiCard.stylingConfiguration:
{"styleObjects":{},"customStyles":".block-header-heading{
 width: 100% !important; 
 background-color: #f3f3f3;
 height: 38px; 
}
.slds-form-element__label{
 padding-botton:10px;
 color: #7E8C8D;
 font-size: 13px;
}
.field-value{
 margin-top: 1px;
 display: block;
}
.field-display{
 height: 50px;
 padding-left:10px;
 padding-top:5px;
 margin-bottom: 5px;
}
.blockSlot{
 padding-left: 4px;
 padding-top: 4px;
 padding-bottom: 3px;
}

/* Tab row container */
.portal-tabs {
 display: block !important;
 width: 100% !important;
 max-width: 100% !important;
 min-height: 42px !important;

 padding: 0 0 0 12px !important;
 margin: 8px 0 8px 0 !important;

 background: #ffffff !important;
 border-bottom: 1px solid #8f8f8f !important;
 box-sizing: border-box !important;
 overflow: visible !important;
}

/* Individual tab action */
.portal-tab {
 display: inline-block !important;

 width: auto !important;
 min-width: auto !important;
 max-width: none !important;
 min-height: 38px !important;

 padding: 10px 0 8px 0 !important;
 margin: 0 36px 0 0 !important;

 background: transparent !important;
 border: 0 !important;
 border-bottom: 3px solid transparent !important;
 border-radius: 0 !important;
 box-shadow: none !important;

 color: #444444 !important;
 font-size: 14px !important;
 font-weight: 400 !important;
 line-height: 18px !important;
 text-align: center !important;
 text-decoration: none !important;
 white-space: nowrap !important;
 word-break: keep-all !important;
 overflow-wrap: normal !important;
 cursor: pointer !important;
 box-sizing: border-box !important;
 vertical-align: bottom !important;
}

/* Keep action text on one line */
.portal-tab *,
.portal-tab button,
.portal-tab a,
.portal-tab span,
.portal-tab .slds-button,
.portal-tab .slds-truncate {
 white-space: nowrap !important;
 word-break: keep-all !important;
 overflow-wrap: normal !important;
 text-align: center !important;
}

/* Remove OmniStudio/Salesforce action button styling */
.portal-tab button,
.portal-tab a,
.portal-tab .slds-button,
.portal-tab .slds-button_brand,
.portal-tab .slds-button_neutral,
.portal-tab .slds-button_stretch {
 display: inline-block !important;

 width: auto !important;
 min-width: auto !important;
 max-width: none !important;
 height: auto !important;
 min-height: 0 !important;

 padding: 0 !important;
 margin: 0 !important;

 background: transparent !important;
 border: 0 !important;
 border-radius: 0 !important;
 box-shadow: none !important;

 color: inherit !important;
 font-size: inherit !important;
 font-weight: inherit !important;
 line-height: inherit !important;
 text-align: center !important;
 text-decoration: none !important;
}

/* Active tab */
.portal-tab-active,
.portal-tab.portal-tab-active {
 color: #1f5d99 !important;
 font-weight: 600 !important;
 border-bottom: 3px solid #2f6fa8 !important;
}

/* Hover/focus */
.portal-tab:hover,
.portal-tab:focus,
.portal-tab:hover *,
.portal-tab:focus * {
 background: transparent !important;
 color: #1f5d99 !important;
 text-decoration: none !important;
 box-shadow: none !important;
}

/* Tab body */
.portal-tab-content {
 width: 100% !important;
 padding: 12px 8px !important;
 background: #ffffff !important;
 box-sizing: border-box !important;
}"}
